    try:
        res = client.get_secret_value(SecretId='prod/db/password')
        return json.loads(res['SecretString'])
    except ClientError as e:
        if e.response['Error']['Code'] == 'ResourceNotFoundException':
            raise

from collections import Counter
import json

def parse_errors(log_path):
    errors = []
    with open(log_path, 'r', encoding='utf-8') as f:
        for line in f:
            try:
                entry = json.loads(line)
                if entry.get('level') == 'ERROR':
                    errors.append(entry)
            except json.JSONDecodeError:
                continue
    common_errors = Counter(e['error_type'] for e in errors if 'error_type' in e).most_common(10)
    return common_errors

from kubernetes import client, config

def scan_pod_resources():
    config.load_kube_config()
    v1 = client.CoreV1Api()
    for pod in v1.list_pod_for_all_namespaces().items:
        for c in pod.spec.containers:
            limits = c.resources.limits if c.resources else None
            requests = c.resources.requests if c.resources else None
            if not limits:
                print(f"{pod.metadata.namespace}/{pod.metadata.name}/{c.name}: NO LIMITS")
            elif not requests:
                print(f"{pod.metadata.namespace}/{pod.metadata.name}/{c.name}: NO REQUESTS")
